parameters.jsCode:
const rawText =
  $json.text ||
  $json.data ||
  $json.content ||
  '';

const cleanText = String(rawText)
  .replace(/\u0000/g, '')
  .replace(/\r/g, '\n')
  .replace(/[ \t]+/g, ' ')
  .replace(/\n{3,}/g, '\n\n')
  .trim();

if (!cleanText || cleanText.length < 100) {
  throw new Error(
    'Could not extract enough text from the CV. Please upload a text-based PDF.'
  );
}

if (cleanText.length > 60000) {
  throw new Error(
    'The CV is too large. Please upload a shorter CV.'
  );
}

return [
  {
    json: {
      cv_text: cleanText,
      cv_character_count: cleanText.length,
      full_name: $('AI CV Analyzer Form').item.json['Full Name'] || '',
      email: $('AI CV Analyzer Form').item.json['Email'] || '',
      job_description:
        $('AI CV Analyzer Form').item.json['Job Description'] || ''
    }
  }
];

const cv = String($json.cv_text || '').trim();
const job = String($json.job_description || '').trim();

if (cv.length < 100) {
  throw new Error('CV content is empty or too short.');
}

if (job.length < 100) {
  throw new Error(
    'Job Description is too short. Please provide the complete job description.'
  );
}

return [
  {
    json: {
      ...$json,
      cv_text: cv,
      job_description: job
    }
  }
];

