parameters.jsCode:
let raw = $json;

// Try common AI output locations
let analysis =
  raw.output ??
  raw.result ??
  raw.response ??
  raw.data ??
  raw;

// If output is JSON text, convert it to an object
if (typeof analysis === 'string') {
  try {
    analysis = JSON.parse(
      analysis
        .replace(/^```json\s*/i, '')
        .replace(/^```\s*/i, '')
        .replace(/```$/i, '')
        .trim()
    );
  } catch (error) {
    throw new Error(
      'Could not parse AI output as JSON. Output: ' +
      analysis.substring(0, 500)
    );
  }
}

// Sometimes Structured Output is nested again
if (analysis.output && typeof analysis.output === 'object') {
  analysis = analysis.output;
}

const scores = analysis.score_breakdown || {};

const requiredSkills = Math.max(
  0,
  Math.min(35, Number(scores.required_skills || 0))
);

const experience = Math.max(
  0,
  Math.min(25, Number(scores.experience || 0))
);

const responsibilities = Math.max(
  0,
  Math.min(15, Number(scores.responsibilities || 0))
);

const education = Math.max(
  0,
  Math.min(10, Number(scores.education_certifications || 0))
);

const ats = Math.max(
  0,
  Math.min(10, Number(scores.ats_keywords || 0))
);

const preferred = Math.max(
  0,
  Math.min(5, Number(scores.preferred_skills || 0))
);

const calculatedScore = Math.round(
  requiredSkills +
  experience +
  responsibilities +
  education +
  ats +
  preferred
);

let matchLevel;

if (calculatedScore >= 90) {
  matchLevel = 'Excellent Match';
} else if (calculatedScore >= 80) {
  matchLevel = 'Very Strong Match';
} else if (calculatedScore >= 70) {
  matchLevel = 'Strong Match';
} else if (calculatedScore >= 60) {
  matchLevel = 'Moderate Match';
} else if (calculatedScore >= 50) {
  matchLevel = 'Weak Match';
} else {
  matchLevel = 'Poor Match';
}

return [
  {
    json: {
      candidate_name:
        $('Validate Input').item.json.full_name || '',

      candidate_email:
        $('Validate Input').item.json.email || '',

      job_description:
        $('Validate Input').item.json.job_description || '',

      candidate_summary:
        analysis.candidate_summary || '',

      technical_skills:
        analysis.technical_skills || [],

      soft_skills:
        analysis.soft_skills || [],

      experience:
        analysis.experience || [],

      education:
        analysis.education || [],

      certifications:
        analysis.certifications || [],

      required_skills:
        analysis.required_skills || [],

      preferred_skills:
        analysis.preferred_skills || [],

      matched_skills:
        analysis.matched_skills || [],

      partially_matched_skills:
        analysis.partially_matched_skills || [],

      missing_skills:
        analysis.missing_skills || [],

      strengths:
        analysis.strengths || [],

      gaps:
        analysis.gaps || [],

      ats_keywords_found:
        analysis.ats_keywords_found || [],

      ats_keywords_missing:
        analysis.ats_keywords_missing || [],

      recommendations:
        analysis.recommendations || [],

      score_breakdown: {
        required_skills: requiredSkills,
        experience,
        responsibilities,
        education_certifications: education,
        ats_keywords: ats,
        preferred_skills: preferred
      },

      match_score: calculatedScore,
      match_level: matchLevel,

      final_verdict:
        analysis.final_verdict || '',

      analyzed_at:
        new Date().toISOString()
    }
  }
];

const data = $('Validate AI Result').item.json;

const escapeHtml = (value = '') =>
  String(value)
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;')
    .replace(/'/g, '&#039;');

const list = (items = [], type = 'normal') => {
  if (!Array.isArray(items) || items.length === 0) {
    return '<p class="empty">None identified</p>';
  }

  return `
    <ul class="${type}">
      ${items.map(item =>
        `<li>${escapeHtml(item)}</li>`
      ).join('')}
    </ul>
  `;
};

const score = Number(data.match_score || 0);

let scoreClass = 'poor';

if (score >= 80) {
  scoreClass = 'excellent';
} else if (score >= 70) {
  scoreClass = 'good';
} else if (score >= 60) {
  scoreClass = 'medium';
} else if (score >= 50) {
  scoreClass = 'weak';
}

const s = data.score_breakdown || {};

const html = `
<!DOCTYPE html>
<html lang="en">

<head>
<meta charset="UTF-8">

<meta name="viewport"
content="width=device-width, initial-scale=1.0">

<title>AI CV Analysis</title>

<style>

