    font-family: Arial, Helvetica, sans-serif;
    color: #182230;
}

.container {
    max-width: 1000px;
    margin: auto;
}

.header {
    background: #ffffff;
    border-radius: 18px;
    padding: 35px;
    margin-bottom: 20px;
    box-shadow: 0 5px 25px rgba(0,0,0,.06);
}

.header h1 {
    margin: 0 0 10px;
    font-size: 32px;
}

.subtitle {
    color: #667085;
}

.score-card {
    margin-top: 25px;
    padding: 30px;
    text-align: center;
    border-radius: 16px;
    background: #101828;
    color: white;
}

