    font-size: 64px;
    font-weight: bold;
}

.score-label {
    font-size: 20px;
    margin-top: 5px;
}

.progress {
    width: 100%;
    height: 14px;
    background: #344054;
    border-radius: 20px;
    margin-top: 20px;
    overflow: hidden;
}

.progress div {
    height: 100%;
    width: ${score}%;
    background: #ffffff;
}

.section {
    background: white;
    margin-bottom: 18px;
    border-radius: 16px;
    padding: 28px;
    box-shadow: 0 5px 25px rgba(0,0,0,.05);
}

.section h2 {
    margin-top: 0;
    font-size: 21px;
}

ul {
    margin: 0;
    padding-left: 22px;
}

li {
    padding: 5px 0;
    line-height: 1.5;
}

.grid {
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: 18px;
}

.score-grid {
    display: grid;
    grid-template-columns: repeat(3,1fr);
    gap: 12px;
}

.metric {
    background: #f9fafb;
    border-radius: 12px;
    padding: 16px;
}

.metric-value {
    font-weight: bold;
    font-size: 22px;
}

