    border-radius: 20px;
    font-size: 13px;
}

.empty {
    color: #98a2b3;
}

.footer {
    text-align: center;
    padding: 25px;
    color: #98a2b3;
    font-size: 12px;
}

@media(max-width:700px) {

    body {
        padding: 15px;
    }

    .grid {
        grid-template-columns: 1fr;
    }

    .score-grid {
        grid-template-columns: 1fr 1fr;
    }

}

</style>
</head>

<body>

<div class="container">

<div class="header">

<h1>AI CV Analysis</h1>

<div class="subtitle">
Candidate:
<strong>${escapeHtml(data.candidate_name || 'Candidate')}</strong>
</div>

<div class="score-card">

<div class="score">
${score}%
</div>

<div class="score-label">
${escapeHtml(data.match_level)}
</div>

<div class="progress">
<div></div>
</div>

</div>

</div>

<div class="section">

<h2>Candidate Summary</h2>

<p>
${escapeHtml(data.candidate_summary)}
</p>

</div>

<div class="section">

<h2>Score Breakdown</h2>

<div class="score-grid">

<div class="metric">
<div class="metric-value">
${s.required_skills || 0}/35
</div>
<div class="metric-name">
Required Skills
</div>
</div>

<div class="metric">
<div class="metric-value">
${s.experience || 0}/25
</div>
